  _setText('top-desc-single', t('topDescSingle'));
  _setText('top-lbl-players', t('topLblPlayers'));
  _setText('top-desc-players',t('topDescPlayers'));
  _setText('disclaimer-text', t('disclaimer'));
  _setText('x-follow-label', t('xFollowLabel'));
  // _setHTML('title-patreon-banner', t('titlePatreonBanner')); // [PATREON] 一時非表示
  document.querySelectorAll('.back-btn').forEach(function(b){b.textContent=t('btnBack');});
  document.querySelectorAll('.formation-decide-btn').forEach(function(b){b.textContent=t('btnDecide');});
  var retryBtn=document.querySelector('.retry-btn'); if(retryBtn) retryBtn.textContent=t('btnRetry');
  var homeBtn=document.querySelector('.home-btn'); if(homeBtn) homeBtn.textContent=t('btnHome');
  var nextBtn=document.getElementById('next-btn'); if(nextBtn) nextBtn.textContent=t('btnNextScene');
  var allBtn=document.getElementById('all-btn'); if(allBtn) allBtn.textContent=t('btnAllEnd');
  var sumBtn=document.getElementById('summary-btn'); if(sumBtn && sumBtn.textContent.indexOf('✨')>=0) sumBtn.textContent=t('btnGenerate');
  var sc=document.getElementById('summary-content');
  if(sc && !sc.querySelector('div')) sc.innerHTML='<span style="color:var(--text-dim);font-size:12px">'+t('summaryPlaceholder')+'</span>';
  document.querySelectorAll('.bench-panel-label').forEach(function(e){e.textContent=t('labelBench');});
  _setText('chance-label-text', t('chanceLabel') + ' ');
  _setText('game-in-progress-label', t('gameInProgress'));
  _setText('share-x-label', t('shareX'));
  _setText('share-img-label', t('shareImg'));
  // 設定画面ラベル
  _setText('label-starting',          t('labelStarting'));
