  _setText('single-desc1',  t('singleDesc1'));
  _setText('single-title2', t('singleTitle2'));
  _setText('single-desc2',  t('singleDesc2'));
  // スクリーンタイトル
  _setText('screen-formation-title',    t('screenFormation'));
  _setText('screen-tactics-title',      t('screenTactics'));
  _setText('screen-keyplayer-title',    t('screenKeyplayer'));
  _setText('screen-marked-title',       t('screenMarked'));
  _setText('screen-result-title',       t('screenResult'));
  _setText('screen-multi-title',        t('screenMulti'));
  _setText('screen-player-detail-title',t('screenPlayerDetail'));
  _setText('screen-players-title',      t('screenPlayers'));
  _setText('setting-title-text',        t('screenSetting'));
  // W杯統計画面
  _setText('screen-worldcup-stats-title', t('wcStatsTitle'));
  _setText('btn-wc-stats', t('wcStatsBtnWC'));
  var _tabMC = document.getElementById('stats-tab-mc'); if(_tabMC) _tabMC.textContent = t('wcStatsTabMC');
  var _tabRe = document.getElementById('stats-tab-real'); if(_tabRe) _tabRe.textContent = t('wcStatsTabReal');
  var _mcRefBtn = document.getElementById('stats-mc-refresh-btn'); if(_mcRefBtn) _mcRefBtn.textContent = t('wcStatsMCRefresh');
  var _reRefBtn = document.getElementById('stats-real-refresh-btn'); if(_reRefBtn) _reRefBtn.textContent = t('wcStatsRealRefresh');
  var _mcSt = document.getElementById('stats-mc-status'); if(_mcSt) _mcSt.textContent = t('wcStatsMCRunning');
  var _reSt = document.getElementById('stats-real-status'); if(_reSt) _reSt.textContent = t('wcStatsRealLoading');
  _setText('players-h1', t('playersTitle'));
  var pb = document.getElementById('patreon-banner-single');
  // if (pb) pb.innerHTML = getPatreonBannerHtml(window.LANG === 'en'); // [PATREON] 一時非表示
  _setText('players-sub', t('playersSub'));
  // 言語切り替え時に選手テーブルを再ビルド
  var playersBody = document.getElementById('players2018-body');
  if (playersBody && playersBody.dataset.built) {
    playersBody.dataset.built = '';
    playersBody.innerHTML = '';
  }
  // W杯モード画面
  _setText('wc-screen-title',  t('wcScreenTitle'));
  _setText('wc-group-label',   t('wcGroupLabel'));
  _setText('wc-th-team',  t('wcColTeam'));
  _setText('wc-th-mp',    t('wcColMP'));
